//! Differential test of the V8 `DateParser` port (`payload_sql_read::date`)
//! against `Date.parse` results generated by test/__rs/read/capture/dates.mjs
//! in several process time zones. The test sets `TZ` to each recorded zone, so
//! it does not depend on the machine's zone. Inputs include lone UTF-16
//! surrogates (decoded losslessly by `payload_sql_read::json`).

use std::path::PathBuf;

use payload_sql_read::Val;
use payload_sql_read::date::{parse_js, set_process_time_zone};
use payload_sql_read::props::{array_items, get};

#[test]
fn date_parse_matches_v8_in_every_recorded_zone() {
  let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../test/__rs/read/dates.json");
  let text = std::fs::read_to_string(&path).expect("read dates.json");
  let json = payload_sql_read::json::parse(&text).expect("parse dates.json");
  let zones = get(&json, "zones").expect("zones");
  let zones = zones.as_obj().expect("zones object").borrow().entries();
  assert!(zones.len() >= 3, "expected at least 3 zones in dates.json");

  let mut failures = Vec::new();
  let mut total = 0;
  for (zone, entry) in zones {
    // SAFETY: the only test in this binary.
    unsafe { set_process_time_zone(Some(&zone.to_string())) };
    let cases = array_items(&get(&entry, "cases").expect("cases")).expect("cases array");
    let mut zone_failures = 0;
    for case in &cases {
      let input = get(case, "input").expect("input");
      let expected = match get(case, "time").expect("time") {
        Val::Num(n) => Some(n),
        _ => None,
      };
      let actual = parse_js(input.as_js_str().expect("string input"));
      let actual = (!actual.is_nan()).then_some(actual);
      if expected != actual {
        zone_failures += 1;
        failures.push(format!("[{zone}] {input:?}: expected {expected:?}, got {actual:?}"));
      }
    }
    total += cases.len();
    println!("dates [{zone}]: {}/{} match", cases.len() - zone_failures, cases.len());
  }
  println!("dates TOTAL: {}/{total} match", total - failures.len());
  assert!(failures.is_empty(), "{}", failures.join("\n"));
}
